                    "sql": "create or replace table prd_db.justherbs.dwh_pandlsummary as select x.*, coalesce(y.date,z.date,m.date,n.date,p.date,q.date,r.date,s.date, t.date, u.date, v.date, w.date, i.date, bm.date,ORDER_TIMESTAMP_PRE)::date as ORDER_TIMESTAMP, upper(coalesce(y.channel_pre, z.channel_pre, m.channel_pre, n.channel_pre, p.channel_pre, q.channel_pre, r.channel_pre, s.channel_pre, t.channel_pre, u.channel_pre, v.channel_pre, w.channel_pre, i.channel_pre,bm.channel_pre,x.channel_pre)) as channel, CASE WHEN MONTH(ORDER_TIMESTAMP::date) >= 4 THEN YEAR(ORDER_TIMESTAMP::date) + 1 ELSE YEAR(ORDER_TIMESTAMP::date) END AS financial_year, div0(ifnull(coalesce(y.spend, z.spend,m.spend, n.spend, p.spend, q.spend, r.spend,s.spend,t.spend, u.spend, v.spend, w.spend,i.spend,bm.spend),0), count(1) over (partition by ORDER_TIMESTAMP::date,upper(channel))) spend from( select m.* ,f.shipping_status ,e.customer_id_final ,case when lower(final_utm_channel) in (\'direct\',\'paytm\',\'cred\',\'jio\',\'google\',\'meta\',\'crm\',\'organic\',\'affiliates (cps)\',\'influencer marketing\',\'partnerships & alliances (cpe)\',\'native ads\',\'influencer marketing\',\'others\',\'googlepay\',\'phonepe\',\'zomato\',\'wishlink\',\'paisawapas\',\'togethr\', \'branding meta\') then upper(final_utm_channel) else \'ALL_OTHERS\' end channel_pre from ( select a.FINAL_UTM_channel_NR ,a.ORDER_TIMESTAMP as ORDER_TIMESTAMP_PRE ,a.ORDER_ID ,a.ORDER_NAME ,sku ,product_name ,product_category ,a.MRP_SALES ,a.TOTAL_SALES ,a.TOTAL_DISCOUNT ,a.DISCOUNT_PERCENT ,a.cancelled_sales ,a.return_sales ,a.NR ,a.TOTAL_COGS ,a.LOGISTICS_COST ,a.SPM_COST ,a.courier_charges ,a.supply_chain_charges ,a.gateway_commission ,a.GC ,a.GC_PERCENT ,a.DISCOUNT_CODE ,a.GC_FILTER ,a.TIMESTAMPED_DATE ,b.final_utm_source ,b.final_utm_channel ,b.shopify_new_customer_flag ,a.tax ,a.shipping_price_without_tax ,a.shipping_price from prd_db.justherbs.DWH_GROSS_CONTRIBUTION_JH a left join ( select order_name, final_utm_source, final_utm_channel, shopify_new_customer_flag, sum(tax) tax from prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS group by 1,2,3,4 ) b on lower(a.ordeR_name) = lower(b.ordeR_name) )m left join ( select distinct reference_code, customer_id_final from prd_db.justherbs.dwh_sales_consolidated ) e on m.ordeR_name = e.reference_code left join (select reference_code, shipping_status from ( select reference_code, shipping_status, row_number() over (partition by reference_code order by 1) rw from prd_db.justherbs.EasyEcom_JH_FACT_ITEMS) where rw = 1) f on replace(m.order_name,\'#\',\'\') = f.reference_code ) x full outer join (select date ,\'GOOGLE\' as channel_pre , sum(spend) spend from prd_db.justherbs.dwh_jh_MARKETING_CONSOLIDATED where channel = \'GOOGLE\' group by 1,2) y on x.ORDER_TIMESTAMP_PRE::date = y.date and upper(x.channel_pre) = upper(y.channel_pre) full outer join (select date ,\'META\' as channel_pre ,sum(spend) spend from prd_db.justherbs.dwh_jh_MARKETING_CONSOLIDATED where channel = \'META\' group by 1,2) z on x.ORDER_TIMESTAMP_PRE::date = z.date and upper(x.channel_pre) = upper(z.channel_pre) full outer join (select date::date as date ,\'AFFILIATES (CPS)\' as channel_pre ,replace(\"Affiliates (CPS)\",\',\',\'\')::float spend from datalake_db.justherbs.trn_spends_jh ) m on x.ORDER_TIMESTAMP_PRE::date = m.date and upper(x.channel_pre) = upper(m.channel_pre) full outer join (select date ,\'CRM\' as channel_pre ,replace(replace(CRM,\',\',\'\'),\'₹\',\'\') spend from datalake_db.justherbs.trn_spends_jh) n on x.ORDER_TIMESTAMP_PRE::date = n.date and uppeR(x.channel_pre) = upper(n.channel_pre) full outer join (select date ,\'NATIVE ADS\' as channel_pre ,replace(\"Native Ads\",\',\',\'\') spend from datalake_db.justherbs.trn_spends_jh) p on x.ORDER_TIMESTAMP_PRE::date = p.date and upper(x.channel_pre) = upper(p.channel_pre) full outer join (select date ,\'OTHERS\' as channel_pre ,replace(OTHERS,\',\',\'\') spend from datalake_db.justherbs.trn_spends_jh) q on x.ORDER_TIMESTAMP_PRE::date = q.date and upper(x.channel_pre) = upper(q.channel_pre) full outer join (select date ,\'INFLUENCER MARKETING\' as channel_pre ,replace(\"Influencer Marketing\",\',\',\'\') spend from datalake_db.justherbs.trn_spends_jh) r on x.ORDER_TIMESTAMP_PRE::date = r.date and upper(x.channel_pre) = upper(r.channel_pre) full outer join (select date ,\'GOOGLEPAY\' as channel_pre ,replace(replace(\"G-Pay\",\',\',\'\'),\'₹\',\'\') spend from datalake_db.justherbs.trn_spends_jh) s on x.ORDER_TIMESTAMP_PRE::date = s.date and upper(x.channel_pre) = upper(s.channel_pre) full outer join (select date ,\'CRED\' as channel_pre ,replace(replace(cred,\',\',\'\'),\'₹\',\'\') spend from datalake_db.justherbs.trn_spends_jh) t on x.ORDER_TIMESTAMP_PRE::date = t.date and upper(x.channel_pre) = upper(t.channel_pre) full outer join (select date ,\'ZOMATO\' as channel_pre ,replace(replace(zomato,\',\',\'\'),\'₹\',\'\') spend from datalake_db.justherbs.trn_spends_jh) u on x.ORDER_TIMESTAMP_PRE::date = u.date and upper(x.channel_pre) = upper(u.channel_pre) full outer join (select date ,\'JIO\' as channel_pre ,replace(replace(jio,\',\',\'\'),\'₹\',\'\') spend from datalake_db.justherbs.trn_spends_jh) v on x.ORDER_TIMESTAMP_PRE::date = v.date and upper(x.channel_pre) = upper(v.channel_pre) full outer join (select date ,\'PHONEPE\' as channel_pre ,replace(replace(phonepe,\',\',\'\'),\'₹\',\'\') spend from datalake_db.justherbs.trn_spends_jh) w on x.ORDER_TIMESTAMP_PRE::date = w.date and upper(x.channel_pre) = upper(w.channel_pre) full outer join (select date ,\'PAYTM\' as channel_pre ,replace(replace(paytm,\',\',\'\'),\'₹\',\'\') spend from datalake_db.justherbs.trn_spends_jh) i on x.ORDER_TIMESTAMP_PRE::date = i.date and upper(x.channel_pre) = upper(i.channel_pre) full outer join (select date ,\'BRANDING META\' as channel_pre ,replace(replace(\"Branding Meta\",\',\',\'\'),\'₹\',\'\') spend from datalake_db.justherbs.trn_spends_jh) bm on x.ORDER_TIMESTAMP_PRE::date = bm.date and upper(x.channel_pre) = upper(bm.channel_pre) ; create or replace table prd_db.justherbs.dwh_cltv as select a.ordeR_month ,div0(sum(total_sales), count(distinct customer_id_final)) aov ,div0(sum(spend), count(distinct customer_id_final)) cac ,div0(count(distinct ordeR_name), count(distinct customer_id_final)) apf ,div0(sum(ifnull(gc, 0)), sum(ifnull(nr, 0))) gc_percent , div0(AOV*div0(sum(ifnull(gc, 0)), sum(ifnull(nr, 0)))*apf,cac) cltv_cac_ratio from ( select distinct date_trunc(\'month\',ORDER_TIMESTAMP::Date) order_month from prd_db.justherbs.dwh_gross_contribution_JH ) a left join prd_db.justherbs.dwh_pandlsummary b on datediff(month,date_trunc(\'month\',b.ORDER_TIMESTAMP::Date),order_month) between 1 and 2 group by 1 order by 1 desc ; create or replace table prd_db.justherbs.dwh_cltv_channel_pre as select a.ordeR_month ,b.channel_pre ,div0(sum(total_sales), count(distinct customer_id_final)) aov ,div0(sum(spend), count(distinct customer_id_final)) cac ,div0(count(distinct ordeR_name), count(distinct customer_id_final)) apf ,div0(sum(ifnull(gc, 0)), sum(ifnull(nr, 0))) gc_percent , div0(AOV*div0(sum(ifnull(gc, 0)), sum(ifnull(nr, 0)))*apf,cac) cltv_cac_ratio from ( select distinct date_trunc(\'month\',ORDER_TIMESTAMP::Date) order_month from prd_db.justherbs.dwh_gross_contribution_jh ) a left join prd_db.justherbs.dwh_pandlsummary b on datediff(month,date_trunc(\'month\',b.ORDER_TIMESTAMP::Date),order_month) between 1 and 2 group by 1,2 order by 1,2 desc ;",
